declare_lint ! { # [doc = " The `non_shorthand_field_patterns` lint detects using `Struct { x: x }`"] # [doc = " instead of `Struct { x }` in a pattern."] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust"] # [doc = " struct Point {"] # [doc = "     x: i32,"] # [doc = "     y: i32,"] # [doc = " }"] # [doc = ""] # [doc = ""] # [doc = " fn main() {"] # [doc = "     let p = Point {"] # [doc = "         x: 5,"] # [doc = "         y: 5,"] # [doc = "     };"] # [doc = ""] # [doc = "     match p {"] # [doc = "         Point { x: x, y: y } => (),"] # [doc = "     }"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " The preferred style is to avoid the repetition of specifying both the"] # [doc = " field name and the binding name if both identifiers are the same."] NON_SHORTHAND_FIELD_PATTERNS , Warn , "using `Struct { x: x }` instead of `Struct { x }` in a pattern" }